INSERT INTO `base_conocimiento` (`id`, `titulo`, `descripcion`, `id_usuario`, `fecha_creacion`) VALUES
(8, 'Algunas publicaciones no se ven', 'Eso se debe a que para crear una publicación, preferimos trabajar bastante en esa publicacación y ademas en el proceso de la edición hay errores que no queremos que se vean en produccion. esta funcionalidad de ocultar las publicaciones solo se puede hacer a nivel de rol de administrador.', 6, '2025-09-10 17:17:51'),
(9, 'Coronación', 'Para poner una coronación en la solución de un problema se debe poner un igual y la pieza que se desea coronar ejemplo: e8=Q', 52, '2025-09-10 17:44:28'),
(10, 'Cuando hay 2 soluciones posibles', 'El sistema reconoce 2 soluciones posibles si se usa esta notacion: Agruparlo en parentisis separando las jugadas con una barra vertical, ejm. Qg1+ (Nxg1|Rxg1) Nf2#', 6, '2025-09-12 15:33:11'),
(11, 'cuando dos piezas pueden ir al mismo lugar', 'Si hay dos piezas iguales que pueden moverse a la misma casilla, hay que poner cuál es la que se mueve específicamente ejm: Qfxe8', 52, '2025-09-13 02:34:22');
