INSERT INTO `publicacion` (`id_publicacion`, `titulo`, `descripcion`, `tipo`, `imagen_publicacion`, `fecha_creacion`, `estado`, `orden`) VALUES
(1, 'Patrones de Mate', 'Aquí se mostrarán diagramas de los diferentes patrones de mate.', 'Problema', 'uploads/publicaciones/68a5f85698315_patrones.png', '2025-07-07 17:26:51', 'activo', 0),
(2, 'El Terrible Gambito Escoces', 'Por primera vez descubre un campo minado donde tu rival caerá en una de esas minas.  El gambito escocés es un arma letal para todo jugador dinámico y agresivo.', 'Estudio', 'uploads/publicaciones/6894f91bc8d3d_gambito_escoces.png', '2025-07-12 04:06:32', 'activo', 4),
(5, 'Grandes Maestros', 'Aquí encontrarás el análisis de posiciones criticas en las partidas de grandes maestros', 'Estudio', 'uploads/publicaciones/68a5f71a31b32_boby.png', '2025-08-07 19:10:49', 'inactivo', 3),
(7, 'Yusupov - Fundamentos 2', 'Es importante la lectura del contenido de cada capítulo antes de intentar resolver los problemas que se recomienda se realicen en un tablero físico para ayudar en su visualización global.', 'Problema', 'uploads/publicaciones/68a5f62ecf1ec_yusupov_2.png', '2025-08-16 03:16:24', 'activo', 2),
(8, 'Arena Chess Trainer', 'Prueba tus conocimientos de táctica.', 'Problema', 'uploads/publicaciones/68a78c7965030_arena_chess_trainer@300x-8.png', '2025-08-21 21:15:37', 'activo', 1),
(9, 'El método Polgar, 5335 problemas', 'Atrevete a resolver estos ejercicios que elevará tu nivel de ajedrez, solo la práctica hace al maestro.', 'Problema', 'uploads/publicaciones/68b634a050fc4_polgar.jpg', '2025-09-02 00:04:48', 'activo', 0),
(11, 'Prueba', 'prueba', 'Estudio', 'uploads/publicaciones/68ce2288a243e_instalaciones.jpg', '2025-09-20 03:42:00', 'inactivo', 0);
